/**
 * The command palette (`design/components/command.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/dialog'
import { normalizeProps } from '@zag-js/solid'

import {
  afresh,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  focusPlace,
  focusReturnTarget,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/command.module.css'
import CommandPanel from './CommandPanel'

export interface CommandItem {
  id: string
  label: string
  icon?: IconRole
  hint?: string
  group?: string
  keywords?: string[]
  disabled?: boolean
  onSelect: () => void
}

export interface CommandProps {
  /**
   * `false` for chained palettes, where the query stays after a command runs.
   */
  closeOnSelect?: boolean
  emptyMessage?: string
  /**
   * The dismiss key label beside the search field (default `esc`). Hosts localize it because a
   * key legend is text too.
   */
  escapeHint?: string
  /**
   * `false` when the app filters the items itself, as with async command sources.
   */
  filter?: false | 'contains'
  items: CommandItem[]
  /**
   * The dialog's accessible name; localized hosts replace the default `Command palette`.
   */
  label?: string
  loading?: boolean
  onOpenChange: (open: boolean) => void
  /**
   * The app owns the ⌘K binding, because a global hotkey is app policy, not vocabulary.
   */
  open: boolean
  placeholder?: string
}

/** The command palette. */
export default function Command(given: CommandProps): JSX.Element {
  const props = mergeProps(
    {
      placeholder: 'Type a command…',
      label: 'Command palette',
      escapeHint: 'esc',
      filter: 'contains',
      loading: false,
      emptyMessage: 'No results',
      closeOnSelect: true,
    } as Defaults<
      CommandProps,
      | 'placeholder'
      | 'label'
      | 'escapeHint'
      | 'filter'
      | 'loading'
      | 'emptyMessage'
      | 'closeOnSelect'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const query = createCell('')
    const returnTo = createCell(null as ReturnType<typeof focusPlace>)
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          finalFocusEl: () => focusReturnTarget(returnTo.value, [panel.value]),
          'aria-label': props.label,
          onEscapeKeyDown: (event) => query.value !== '' && event.preventDefault(),
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const scrimPresent = usePresence(
      () => api.value.open,
      () => scrim.value,
      'dialog.scrim',
    )
    const panelPresent = usePresence(
      () => api.value.open,
      () => panel.value,
      'command.panel',
      { side: 'bottom', align: 'center' },
    )
    const effect1 = () => {
      void (api.value.open && (returnTo.value = focusPlace(document.activeElement)))
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Command',
        element: () => panel.value,
        state: () => ({
          open: api.value.open,
          items: props.items.map((item) => ({
            id: item.id,
            label: item.label,
            ...(item.disabled === true ? { disabled: true } : {}),
          })),
          query: api.value.open ? query.value : '',
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) => (
              props.items.find((item) => item.id === value)?.onSelect(),
              api.value.open && props.closeOnSelect && api.value.setOpen(false)
            ),
          },
          close: () => api.value.open && api.value.setOpen(false),
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <Portal>
        {afresh(() => (
          <>
            {scrimPresent() ? (
              <div
                {...mergeParts(api.value.getBackdropProps(), {
                  class: styles.scrim,
                  hidden: undefined,
                })}
                ref={scrim.attach}
              />
            ) : null}
            {panelPresent() ? (
              <div {...mergeParts(api.value.getPositionerProps(), { class: styles.positioner })}>
                {/* panel */}
                <div
                  {...mergeParts(api.value.getContentProps(), {
                    class: styles.panel,
                    hidden: undefined,
                    'aria-describedby': undefined,
                    'data-loading': props.loading ? '' : undefined,
                    'data-member': 'command',
                  })}
                  ref={panel.attach}
                >
                  <CommandPanel
                    items={props.items}
                    placeholder={props.placeholder}
                    escapeHint={props.escapeHint}
                    filter={props.filter}
                    loading={props.loading}
                    emptyMessage={props.emptyMessage}
                    onQueryChange={($event) => (query.value = $event)}
                    onCommand={() => props.closeOnSelect && api.value.setOpen(false)}
                  />
                </div>
              </div>
            ) : null}
          </>
        ))}
      </Portal>
    )
  })
}
